insert into public.listings (id, seller_id, brand, model, version, model_year, manufacture_year, fuel, transmission, body_type, km, color, city, state, fipe_code, fipe_price, fipe_reference_month, price_mode, repasse_price, final_price, description, condition, photos, status, views, created_at, updated_at) values
  ('l-onix-21-recife', '00000000-0000-4000-8000-000000000101', 'Chevrolet', 'Onix', '1.0 Flex Manual', 2021, 2020, 'flex', 'manual', 'hatch', 48000, 'Prata', 'Recife', 'PE', '004519-5', 59052, 'setembro de 2026', 'ambos', 48400, 55500, 'Onix 1.0 manual muito conservado, único dono, todas as revisões na concessionária (manual e nota). Pneus com uns 60% de vida. Tem um risco pequeno no para-choque traseiro, fora isso tudo certo. Preço de repasse para quem leva no estado; no preço final vai revisado e com garantia de motor e câmbio de 3 meses.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":true,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/onix.jpg'], 'ativo', 312, '2026-09-28T22:49:08.182Z', '2026-09-28T22:49:08.182Z'),
  ('l-hb20-20-fortaleza', '00000000-0000-4000-8000-000000000102', 'Hyundai', 'HB20', '1.0 Turbo Diamond Automático', 2020, 2019, 'flex', 'automatico', 'hatch', 52000, 'Branco', 'Fortaleza', 'CE', '015171-8', 73203, 'setembro de 2026', 'repasse', 62200, null, 'HB20 Diamond turbo automático, o top de linha. Central multimídia com CarPlay, câmera de ré, rodas 16. Para-brisa trincado no canto do passageiro (já está no preço). Revisões em dia até 50 mil. Repasse para lojista, sem enrolação, documento pronto para transferir.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/hb20.jpg'], 'ativo', 198, '2026-09-27T16:49:08.182Z', '2026-09-27T16:49:08.182Z'),
  ('l-gol-18-salvador', '00000000-0000-4000-8000-000000000104', 'Volkswagen', 'Gol', '1.0 Track', 2018, 2017, 'flex', 'manual', 'hatch', 98000, 'Branco', 'Salvador', 'BA', '005469-0', 47648, 'setembro de 2026', 'repasse', 37200, null, 'Gol Track 1.0, carro de leilão (recuperado de financiamento, sem batida). Motor bom, sem fumaça, embreagem já pedindo troca. Lataria com marcas de uso. Ideal para quem tem oficina ou quer rodar Uber. Leilão informado desde já, sem surpresa na hora da vistoria.', '{"hasAuctionHistory":true,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":false,"hasSpareKey":true}'::jsonb, array['/demo/gol.jpg'], 'ativo', 87, '2026-09-29T19:49:08.182Z', '2026-09-29T19:49:08.182Z'),
  ('l-strada-22-recife', '00000000-0000-4000-8000-000000000101', 'Fiat', 'Strada', '1.3 Freedom Cabine Dupla', 2022, 2021, 'flex', 'manual', 'picape', 58000, 'Vermelho', 'Recife', 'PE', '001530-0', 89151, 'setembro de 2026', 'final', null, 90900, 'Strada Freedom cabine dupla, pronta para trabalho ou passeio. Capota marítima, protetor de caçamba, engate. Revisada na loja: óleo, filtros, pastilhas e alinhamento feitos. Aceitamos troca e financiamos. Garantia de 90 dias em motor e câmbio.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":true,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/strada.jpg'], 'ativo', 421, '2026-09-26T21:49:08.182Z', '2026-09-26T21:49:08.182Z'),
  ('l-compass-19-campinas', '00000000-0000-4000-8000-000000000103', 'Jeep', 'Compass', '2.0 Longitude Automático', 2019, 2018, 'flex', 'automatico', 'suv', 87000, 'Preto', 'Campinas', 'SP', '017046-1', 90507, 'setembro de 2026', 'ambos', 79600, 86900, 'Compass Longitude 2.0 flex automático. Bancos em couro, teto solar, multimídia original. Pneus trocados há 5 mil km. Tem pequenos amassados de estacionamento na porta traseira direita. No repasse vai do jeito que está; no preço final entregamos com martelinho feito e polimento.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/compass.jpg'], 'ativo', 276, '2026-09-24T22:49:08.182Z', '2026-09-24T22:49:08.182Z'),
  ('l-corolla-20-bh', '00000000-0000-4000-8000-000000000105', 'Toyota', 'Corolla', '2.0 XEi Automático', 2020, 2019, 'flex', 'cvt', 'sedan', 71000, 'Prata', 'Belo Horizonte', 'MG', '002111-3', 114373, 'setembro de 2026', 'final', null, 108700, 'Corolla XEi 2020 de médico, rodou quase só estrada. Revisões todas na Toyota com carimbo no manual. Interior impecável, sem cheiro de cigarro. Estou intermediando a venda, o dono aceita vistoria cautelar por conta do comprador em qualquer empresa.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":true,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/corolla.jpg'], 'ativo', 350, '2026-09-25T20:49:08.182Z', '2026-09-25T20:49:08.182Z'),
  ('l-civic-18-jp', '00000000-0000-4000-8000-000000000106', 'Honda', 'Civic', '2.0 EXL Automático', 2018, 2017, 'flex', 'cvt', 'sedan', 102000, 'Preto', 'João Pessoa', 'PB', '014090-2', 106684, 'setembro de 2026', 'final', null, 103500, 'Vendo meu Civic EXL 2018, carro de família. Troquei a correia e fiz a revisão dos 100 mil agora. Tem um arranhado no para-choque dianteiro e o banco do motorista com desgaste na lateral. Documento em dia, IPVA 2026 pago. Só venda, não pego troca.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/civic.jpg'], 'vendido', 505, '2026-09-08T21:49:08.182Z', '2026-09-08T21:49:08.182Z'),
  ('l-kwid-21-natal', '00000000-0000-4000-8000-000000000107', 'Renault', 'Kwid', '1.0 Intense', 2021, 2020, 'flex', 'manual', 'hatch', 39000, 'Branco', 'Natal', 'RN', '025267-0', 41533, 'setembro de 2026', 'final', null, 38200, 'Kwid Intense 2021, sou a única dona e usei só para ir ao trabalho. Econômico demais, faz 14 km/l na cidade. Perdi a chave reserva, por isso o preço um pouco abaixo. Revisões feitas na Renault até 30 mil. Pode vir ver em Natal a qualquer hora.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":true,"hasServiceRecords":true,"hasSpareKey":false}'::jsonb, array['/demo/kwid.jpg'], 'ativo', 164, '2026-09-23T14:49:08.182Z', '2026-09-23T14:49:08.182Z'),
  ('l-tcross-23-fortaleza', '00000000-0000-4000-8000-000000000102', 'Volkswagen', 'T-Cross', '200 TSI Automático', 2023, 2022, 'flex', 'automatico', 'suv', 23000, 'Cinza', 'Fortaleza', 'CE', '005510-7', 98777, 'setembro de 2026', 'repasse', 89900, null, 'T-Cross 200 TSI 2023 com 23 mil km, ainda na garantia de fábrica. Carro de repasse de cliente que trocou por um maior. Sem detalhes de lataria, pneus originais. Preço de repasse para girar rápido, documento no nome da loja.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":true,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/t-cross.jpg'], 'ativo', 230, '2026-09-28T20:49:08.182Z', '2026-09-28T20:49:08.182Z'),
  ('l-hilux-19-salvador', '00000000-0000-4000-8000-000000000104', 'Toyota', 'Hilux', '2.8 SRV 4x4 CD Diesel', 2019, 2018, 'diesel', 'automatico', 'picape', 138000, 'Prata', 'Salvador', 'BA', '002143-1', 179514, 'setembro de 2026', 'repasse', 154400, null, 'Hilux SRV 2.8 diesel 4x4, rodou em fazenda mas sempre com manutenção em dia (notas das revisões). Está alienada ao banco, o saldo é quitado no ato da venda com o dinheiro do comprador, tudo dentro do banco. Pneus BF novos. Motor forte, sem vazamento.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":true,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/hilux.jpg'], 'ativo', 610, '2026-09-21T12:49:08.182Z', '2026-09-21T12:49:08.182Z'),
  ('l-renegade-18-recife', '00000000-0000-4000-8000-000000000101', 'Jeep', 'Renegade', '1.8 Automático', 2018, 2017, 'flex', 'automatico', 'suv', 94000, 'Vermelho', 'Recife', 'PE', '017062-3', 66973, 'setembro de 2026', 'repasse', 50200, null, 'Renegade 1.8 automático com sinistro: batida de frente com acionamento de airbag, já reparado (airbags trocados, longarina sem dano segundo o laudo). Laudo cautelar disponível, reprovado por causa do sinistro. Por isso 25% abaixo da FIPE. Só para quem sabe o que está comprando.', '{"hasAuctionHistory":false,"hasAccidentHistory":true,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":false,"hasSpareKey":true}'::jsonb, array['/demo/renegade.jpg'], 'ativo', 489, '2026-09-27T13:49:08.182Z', '2026-09-27T13:49:08.182Z'),
  ('l-argo-20-bh', '00000000-0000-4000-8000-000000000105', 'Fiat', 'Argo', '1.0 Firefly', 2020, 2019, 'flex', 'manual', 'hatch', 61000, 'Vermelho', 'Belo Horizonte', 'MG', '001509-1', 51159, 'setembro de 2026', 'ambos', 44500, 48600, 'Argo 1.0 Firefly, motor 3 cilindros bem econômico. Ar, direção elétrica, vidros e travas. Um amassadinho na tampa do porta-malas. No repasse sai como está; no preço final o dono entrega com a funilaria feita e revisão de 60 mil paga.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/argo.jpg'], 'ativo', 143, '2026-09-19T11:49:08.182Z', '2026-09-19T11:49:08.182Z'),
  ('l-polo-22-campinas', '00000000-0000-4000-8000-000000000103', 'Volkswagen', 'Polo', '200 TSI Comfortline Automático', 2022, 2021, 'flex', 'automatico', 'hatch', 34000, 'Azul', 'Campinas', 'SP', '005477-1', 83923, 'setembro de 2026', 'final', null, 80600, 'Polo 200 TSI Comfortline 2022 azul, lindo. Painel digital, multimídia, sensor de estacionamento. Revisões na VW até 30 mil. Aceitamos seu carro na troca e financiamos em até 60x. Garantia da loja de 6 meses em motor e câmbio.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":true,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/polo.jpg'], 'ativo', 190, '2026-09-17T12:49:08.182Z', '2026-09-17T12:49:08.182Z'),
  ('l-onix-14-goiania', '00000000-0000-4000-8000-000000000108', 'Chevrolet', 'Onix', '1.4 LT Manual', 2014, 2013, 'flex', 'manual', 'hatch', 142000, 'Preto', 'Goiânia', 'GO', '004425-3', 45677, 'setembro de 2026', 'repasse', 37900, null, 'Onix LT 1.4 2014, carro de uso diário. Tem IPVA 2026 atrasado e duas multas (uns R$ 1.900 no total), dá para descontar do valor ou eu pago na transferência. Mecânica boa, suspensão fazendo um barulhinho na frente. Aceito proposta à vista.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":true,"singleOwner":false,"hasServiceRecords":false,"hasSpareKey":true}'::jsonb, array['/demo/onix-2014.jpg'], 'ativo', 98, '2026-09-26T20:49:08.182Z', '2026-09-26T20:49:08.182Z'),
  ('l-creta-21-fortaleza', '00000000-0000-4000-8000-000000000102', 'Hyundai', 'Creta', '1.6 Action Automático', 2021, 2020, 'flex', 'automatico', 'suv', 66000, 'Prata', 'Fortaleza', 'CE', '015190-4', 88153, 'setembro de 2026', 'repasse', 78500, null, 'Creta 1.6 Action automático 2021. Carro de repasse de cliente, sem retoque de pintura. Multimídia com espelhamento, câmera de ré. Pneus dianteiros novos. Documentação ok para transferir na hora. Repasse para lojista ou corretor.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/creta.jpg'], 'ativo', 175, '2026-09-23T15:49:08.182Z', '2026-09-23T15:49:08.182Z'),
  ('l-toro-20-salvador', '00000000-0000-4000-8000-000000000104', 'Fiat', 'Toro', '2.0 Endurance 4x4 Diesel', 2020, 2019, 'diesel', 'automatico', 'picape', 112000, 'Branco', 'Salvador', 'BA', '001520-2', 93446, 'setembro de 2026', 'ambos', 84100, 90600, 'Toro Endurance 2.0 diesel 4x4 automática. Usada em obra, caçamba com marcas de uso e protetor. Motor e câmbio perfeitos, troca de óleo a cada 10 mil com nota. Repasse no estado; no preço final vai com caçamba repintada e revisão completa.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/toro.jpg'], 'ativo', 340, '2026-09-20T18:49:08.182Z', '2026-09-20T18:49:08.182Z'),
  ('l-hb20-24-jp', '00000000-0000-4000-8000-000000000106', 'Hyundai', 'HB20', '1.0 Comfort Manual', 2024, 2023, 'flex', 'manual', 'hatch', 12000, 'Branco', 'João Pessoa', 'PB', '015215-3', 70180, 'setembro de 2026', 'final', null, 72300, 'HB20 Comfort 2024 com só 12 mil km, praticamente zero. Ainda tem 4 anos de garantia de fábrica. Estou vendendo porque vou mudar de cidade. Tem película, tapetes e alarme. Preço um pouco acima da FIPE por causa do km baixíssimo, mas aceito conversar.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":true,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/hb20-2024.jpg'], 'ativo', 120, '2026-09-27T22:49:08.182Z', '2026-09-27T22:49:08.182Z'),
  ('l-tracker-23-recife', '00000000-0000-4000-8000-000000000101', 'Chevrolet', 'Tracker', '1.0 Turbo Automático', 2023, 2022, 'flex', 'automatico', 'suv', 19000, 'Cinza', 'Recife', 'PE', '004526-8', 91789, 'setembro de 2026', 'repasse', 85400, null, 'Tracker 1.0 turbo automático 2023, 19 mil km, garantia GM. Chegou hoje na loja, ainda vai para a vitrine. Sem nenhum detalhe. Repasse com preço de ocasião para quem fechar primeiro.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":true,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/tracker.jpg'], 'ativo', 58, '2026-09-29T12:49:08.182Z', '2026-09-29T12:49:08.182Z'),
  ('l-virtus-21-campinas', '00000000-0000-4000-8000-000000000103', 'Volkswagen', 'Virtus', '200 TSI Comfortline Automático', 2021, 2020, 'flex', 'automatico', 'sedan', 57000, 'Prata', 'Campinas', 'SP', '005485-2', 78106, 'setembro de 2026', 'final', null, 73400, 'Virtus 200 TSI Comfortline automático. Porta-malas enorme, ideal para família ou aplicativo premium. Revisado na loja, pneus meia vida. Pequeno arranhão no retrovisor esquerdo. Financiamento com entrada a partir de 20%.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/virtus.jpg'], 'ativo', 211, '2026-09-15T15:49:08.182Z', '2026-09-15T15:49:08.182Z'),
  ('l-gol-12-natal', '00000000-0000-4000-8000-000000000107', 'Volkswagen', 'Gol', '1.6 Power 4 portas', 2012, 2011, 'flex', 'manual', 'hatch', 168000, 'Prata', 'Natal', 'RN', '005277-9', 32296, 'setembro de 2026', 'repasse', 25800, null, 'Gol 1.6 Power 2012, comprei já com passagem por leilão (consta no documento). Motor 1.6 forte, ar gelando. Tem ferrugem no pé da porta traseira e o banco de trás rasgado. Carro honesto para o dia a dia, preço baixo justamente pelo leilão.', '{"hasAuctionHistory":true,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":false,"hasSpareKey":false}'::jsonb, array['/demo/gol-2012.jpg'], 'ativo', 77, '2026-09-13T17:49:08.182Z', '2026-09-13T17:49:08.182Z'),
  ('l-mobi-19-goiania', '00000000-0000-4000-8000-000000000108', 'Fiat', 'Mobi', '1.0 Drive', 2019, 2018, 'flex', 'manual', 'hatch', 73000, 'Branco', 'Goiânia', 'GO', '001480-0', 43034, 'setembro de 2026', 'repasse', 36100, null, 'Mobi Drive 1.0 2019, carro de entrada muito econômico. Ar, direção, vidros elétricos na frente. Pneus trocados ano passado. Um amassado pequeno no para-lama. Pausei o anúncio enquanto resolvo a transferência de um débito antigo.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/mobi.jpg'], 'pausado', 66, '2026-09-04T16:49:08.182Z', '2026-09-04T16:49:08.182Z'),
  ('l-ccross-22-bh', '00000000-0000-4000-8000-000000000105', 'Toyota', 'Corolla Cross', '2.0 XRE Automático', 2022, 2021, 'flex', 'cvt', 'suv', 44000, 'Cinza', 'Belo Horizonte', 'MG', '002203-9', 127400, 'setembro de 2026', 'final', null, 124900, 'Corolla Cross XRE 2022, cliente meu trocou por um híbrido. Todas as revisões na Toyota, pneus Bridgestone originais com 60%. Sem batida, sem retoque. Aceita vistoria cautelar e financiamento. Carro para quem quer SUV sem dor de cabeça.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":true,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/corolla-cross.jpg'], 'ativo', 402, '2026-09-22T16:49:08.182Z', '2026-09-22T16:49:08.182Z'),
  ('l-yaris-21-fortaleza', '00000000-0000-4000-8000-000000000102', 'Toyota', 'Yaris', '1.5 S Automático', 2021, 2020, 'flex', 'cvt', 'hatch', 49000, 'Vermelho', 'Fortaleza', 'CE', '002198-9', 84212, 'setembro de 2026', 'ambos', 76600, 82500, 'Yaris S 1.5 automático CVT, câmbio suave e motor confiável. Chave presencial, partida no botão. Repasse para loja no estado atual (precisa de higienização interna); preço final com higienização, polimento e revisão de 50 mil.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/yaris.jpg'], 'ativo', 133, '2026-09-18T21:49:08.182Z', '2026-09-18T21:49:08.182Z'),
  ('l-s10-18-salvador', '00000000-0000-4000-8000-000000000104', 'Chevrolet', 'S10', '2.8 100 Years 4x4 CD Diesel', 2018, 2017, 'diesel', 'automatico', 'picape', 156000, 'Preto', 'Salvador', 'BA', '004485-7', 159883, 'setembro de 2026', 'repasse', 139100, null, 'S10 100 Years 2.8 diesel 4x4 automática, edição especial. Km alto mas de estrada, manutenção em concessionária até 120 mil e depois em oficina especializada (notas guardadas). Turbina revisada há 10 mil km. Preço de repasse, não faço garantia.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/s10.jpg'], 'ativo', 288, '2026-09-11T22:49:08.182Z', '2026-09-11T22:49:08.182Z'),
  ('l-hrv-19-campinas', '00000000-0000-4000-8000-000000000103', 'Honda', 'HR-V', '1.8 EX Automático', 2019, 2018, 'flex', 'cvt', 'suv', 81000, 'Prata', 'Campinas', 'SP', '014087-2', 98707, 'setembro de 2026', 'final', null, 93800, 'HR-V EX 1.8 automático, bancos em couro, multimídia, câmera de ré. Revisões na Honda. Vendido para um cliente de Sumaré, mas deixo o anúncio para quem quiser ver o padrão dos nossos carros.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/hr-v.jpg'], 'vendido', 377, '2026-08-30T17:49:08.182Z', '2026-08-30T17:49:08.182Z'),
  ('l-duster-18-recife', '00000000-0000-4000-8000-000000000101', 'Renault', 'Duster', '1.6 Authentique Automático', 2018, 2017, 'flex', 'cvt', 'suv', 104000, 'Cinza', 'Recife', 'PE', '025274-3', 63249, 'setembro de 2026', 'repasse', 51200, null, 'Duster 1.6 automático CVT 2018. Câmbio já revisado (troca de fluido feita). Lataria com riscos de uso e para-choque traseiro com pintura queimada. Mecânica em ordem. Repasse para lojista ou quem quer um SUV barato para o dia a dia.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/duster.jpg'], 'ativo', 156, '2026-09-16T22:49:08.182Z', '2026-09-16T22:49:08.182Z'),
  ('l-kicks-20-jp', '00000000-0000-4000-8000-000000000106', 'Nissan', 'Kicks', '1.6 S Automático', 2020, 2019, 'flex', 'cvt', 'suv', 58000, 'Prata', 'João Pessoa', 'PB', '023156-8', 78510, 'setembro de 2026', 'final', null, 75400, 'Kicks S 1.6 automático 2020, sou o primeiro dono. Uso para trabalho em João Pessoa, nunca pegou estrada de terra. Revisões feitas na Nissan até 50 mil. Um amassado leve na porta do motorista. Pode trazer seu mecânico ou fazer cautelar.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":true,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/kicks.jpg'], 'ativo', 142, '2026-09-25T12:49:08.182Z', '2026-09-25T12:49:08.182Z'),
  ('l-cronos-23-bh', '00000000-0000-4000-8000-000000000105', 'Fiat', 'Cronos', '1.3 Drive', 2023, 2022, 'flex', 'manual', 'sedan', 21000, 'Prata', 'Belo Horizonte', 'MG', '001505-9', 73262, 'setembro de 2026', 'final', null, 72500, 'Cronos Drive 1.3 2023, sedã econômico com porta-malas de 525 litros. Ainda na garantia Fiat. Carro de professora, só cidade. Preço praticamente na FIPE porque está como novo. Estou intermediando, atendo em BH e região.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":true,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/cronos.jpg'], 'ativo', 95, '2026-09-09T11:49:08.182Z', '2026-09-09T11:49:08.182Z'),
  ('l-onixplus-22-fortaleza', '00000000-0000-4000-8000-000000000102', 'Chevrolet', 'Onix Plus', '1.0 Turbo Automático', 2022, 2021, 'flex', 'automatico', 'sedan', 41000, 'Branco', 'Fortaleza', 'CE', '004499-7', 69856, 'setembro de 2026', 'repasse', 61500, null, 'Onix Plus 1.0 turbo automático, ex-aplicativo com manutenção rigorosa (todas as notas). Bancos com capa desde o primeiro dia. Pausado enquanto passa por polimento, volta em breve com fotos novas.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/onix-plus.jpg'], 'pausado', 201, '2026-09-02T13:49:08.182Z', '2026-09-02T13:49:08.182Z'),
  ('l-strada-22-goiania', '00000000-0000-4000-8000-000000000108', 'Fiat', 'Strada', '1.3 Freedom Cabine Dupla', 2022, 2021, 'flex', 'manual', 'picape', 88000, 'Branco', 'Goiânia', 'GO', '001530-0', 89151, 'setembro de 2026', 'final', null, 82900, 'Strada Freedom CD 2022 branca. Uso em fazenda aqui perto de Goiânia, mas sem judiar: óleo trocado certinho, pneus All Terrain seminovos. Caçamba com riscos. Estou vendendo para comprar uma diesel. Documento em dia.', '{"hasAuctionHistory":false,"hasAccidentHistory":false,"isFinanced":false,"hasDebts":false,"singleOwner":false,"hasServiceRecords":true,"hasSpareKey":true}'::jsonb, array['/demo/strada.jpg'], 'ativo', 187, '2026-09-24T15:49:08.182Z', '2026-09-24T15:49:08.182Z')
